-- | Noise KKpsk2 against vectors made with the Python noiseprotocol
-- library, the one aiosendspin uses: fixed static, ephemeral and PSK
-- keys on both sides, the initiator's messages compared byte for byte,
-- and the responder's read and decrypted. Generated by:
--
-- > I = NoiseConnection.from_name(b"Noise_KKpsk2_<suite>"); R = ...
-- > set the static keys (si = bytes 1..32, sr = bytes 33..64), the
-- > ephemerals (ei = 65..96, er = 97..128), the PSK (32 bytes of 0xa5)
-- > and the prologue on both; m1 = I.write_message(p1);
-- > m2 = R.write_message(b"{}"); then two transport messages each way:
-- > I.encrypt(b"\x00server/hello"), I.encrypt(b"second"),
-- > R.encrypt(b"\x00client/hello"), R.encrypt(b"reply two").
module NoiseSpec (spec) where

import Data.ByteArray.Encoding (Base (Base16), convertFromBase)
import Data.ByteString (ByteString)
import Data.ByteString.Char8 qualified as Char8
import Data.Maybe (fromJust, isNothing)
import Nixtune.Sendspin.Noise
import Nixtune.Sendspin.PskId (mkPsk, sentinelPsk)
import Test.Hspec

data Vector = Vector
  { vSuite :: Suite
  , vStatic :: ByteString
  , vRemote :: ByteString
  , vEphemeral :: ByteString
  , vPsk :: ByteString
  , vPrologue :: ByteString
  , vPayload1 :: ByteString
  , vMessage1 :: ByteString
  , vMessage2 :: ByteString
  , vInitiatorSends :: [ByteString]
  , vResponderSends :: [ByteString]
  }

hex :: ByteString -> ByteString
hex = either error id . convertFromBase Base16

vectors :: [Vector]
vectors =
  [
  Vector
    { vSuite = ChaChaPoly
    , vStatic = "0102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f20"
    , vRemote = "5869aff450549732cbaaed5e5df9b30a6da31cb0e5742bad5ad4a1a768f1a67b"
    , vEphemeral = "4142434445464748494a4b4c4d4e4f505152535455565758595a5b5c5d5e5f60"
    , vPsk = "a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5"
    , vPrologue = "7b2274797065223a22636c69656e742f696e6974227d7b2274797065223a227365727665722f696e6974227d"
    , vPayload1 = "7b2270736b5f6964223a2278222c2270736b5f63617465676f7279223a226c74227d"
    , vMessage1 = "64b101b1d0be5a8704bd078f9895001fc03e8e9f9522f188dd128d9846d48466d3935f1b7ca29eba9acd42d05cc2a0f6b817fb1df9c8220c87610215d86bcc32db5c58cd1b76ffe2c5684b7276d7e66631b3"
    , vMessage2 = "244fe3b963e899dd295baffce248d3530f3a9a7479ba063002680ebfe7adad4942a69028784cf2a589c85d588be53129bb7e"
    , vInitiatorSends = ["22ff682893e753a4b25903758b78940db9ca2700a97bc600d39718ae5f", "579cc7b8d2402febe221d495c88c330b760c7eb57c28"]
    , vResponderSends = ["43e90e2f399809e473700e69b8b661f36ca510c5180c1f5dadc4781707", "0cce5c7f9fa84bca5119f66ccadd49443f2da831cd04cd6dcf"]
    }
  ,
  Vector
    { vSuite = AesGcm
    , vStatic = "0102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f20"
    , vRemote = "5869aff450549732cbaaed5e5df9b30a6da31cb0e5742bad5ad4a1a768f1a67b"
    , vEphemeral = "4142434445464748494a4b4c4d4e4f505152535455565758595a5b5c5d5e5f60"
    , vPsk = "a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5a5"
    , vPrologue = "7b2274797065223a22636c69656e742f696e6974227d7b2274797065223a227365727665722f696e6974227d"
    , vPayload1 = "7b2270736b5f6964223a2278222c2270736b5f63617465676f7279223a226c74227d"
    , vMessage1 = "64b101b1d0be5a8704bd078f9895001fc03e8e9f9522f188dd128d9846d484666e34496dc391082b306f45e9ed4830cff2bb2abb80fb177448dbca31e3a5c0aaaa4c9d82ea347614f1bf4e590203460a6c1d"
    , vMessage2 = "244fe3b963e899dd295baffce248d3530f3a9a7479ba063002680ebfe7adad4986683a5ad788392fb6637ce0ae6410f57448"
    , vInitiatorSends = ["f68c887254952d355d93e722e738c1d7409def2d1171bfa78e354fdf0e", "261fb9e30fdfa3ac30634063624a5e48eb03bdcb97f9"]
    , vResponderSends = ["7944a278ace741de5fb68a093c2573921a0d7e0f7df749199767810dc5", "76a5366f97b4971aada4d7b1e798a2705e469b6c31247d9e16"]
    }
  ]

message1 :: Vector -> (ByteString, AfterMessage1)
message1 v =
  writeMessage1
    (vSuite v)
    (fromJust (mkStaticKey (hex (vStatic v))))
    (fromJust (mkPublicKey (hex (vRemote v))))
    (hex (vPrologue v))
    (fromJust (mkEphemeral (hex (vEphemeral v))))
    (hex (vPayload1 v))

spec :: Spec
spec = describe "KKpsk2 as the initiator" $
  mapM_ suite vectors
  where
    suite v = describe (show (vSuite v)) $ do
      let (m1, st) = message1 v
          psk = fromJust (mkPsk (hex (vPsk v)))
      it "writes message 1 as noiseprotocol does" $
        m1 `shouldBe` hex (vMessage1 v)
      it "reads message 2 and its empty-object payload" $
        fmap fst (readMessage2 st psk (hex (vMessage2 v))) `shouldBe` Just (Char8.pack "{}")
      it "refuses message 2 under another PSK" $
        isNothing (readMessage2 st sentinelPsk (hex (vMessage2 v))) `shouldBe` True
      it "encrypts and decrypts transport messages as noiseprotocol does" $ do
        let tr = snd (fromJust (readMessage2 st psk (hex (vMessage2 v))))
            (a, s1) = encrypt (sending tr) (Char8.pack "\0server/hello")
            (b, _) = encrypt s1 (Char8.pack "second")
        [a, b] `shouldBe` map hex (vInitiatorSends v)
        case vResponderSends v of
          [first, second] -> do
            let (x, r1) = fromJust (decrypt (receiving tr) (hex first))
                (y, _) = fromJust (decrypt r1 (hex second))
            [x, y] `shouldBe` [Char8.pack "\0client/hello", Char8.pack "reply two"]
          _ -> expectationFailure "a vector carries two responder messages"
      it "refuses a transport message out of order" $ do
        let tr = snd (fromJust (readMessage2 st psk (hex (vMessage2 v))))
        case vResponderSends v of
          [_, second] -> isNothing (decrypt (receiving tr) (hex second)) `shouldBe` True
          _ -> expectationFailure "a vector carries two responder messages"
